<html lang="hu">
<head>
    <meta charset="UTF-8">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
    <meta name="description" content="TiffyTime AI Asszisztens - Fejlett chat és mély kutatási képességek.">
    <meta name="theme-color" content="#000000">
    <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🤖</text></svg>">
    <title>TiffyTime</title>
    <script src="" xintegrity="sha512-dLxCCzGTT9jDQDpbUiZEQPOlCPHfOI_gOJJmVHRplJ7BcmBBYRBLjDNdUNEOPbHTjVUpSHTN6qitH/rIvP/+Mg==" crossorigin="anonymous" referrerpolicy="no-referrer"></script>
    <style>
        :root {
            --bg-color: #000000;
            --header-footer-bg: rgba(10, 10, 10, 0.6);
            --ai-bubble-bg: rgba(0, 30, 60, 0.4);
            --user-bubble-bg: linear-gradient(135deg, rgba(0, 122, 255, 0.8), rgba(0, 86, 179, 0.8));
            --widget-bg: rgba(28, 28, 30, 0.4);
            --widget-border: rgba(255, 255, 255, 0.06);
            --text-primary: #FFFFFF;
            --text-secondary: #A1A1AA;
            --input-bg: rgba(28, 28, 30, 0.6);
            --accent-blue: #2997FF;
            --accent-research-gradient: var(--user-bubble-bg);
            --safe-top: env(safe-area-inset-top);
            --safe-bottom: env(safe-area-inset-bottom);
            --sidebar-width: 280px;
        }

        #sidebar {
            position: fixed;
            top: 0;
            left: 0;
            width: var(--sidebar-width);
            height: 100vh;
            background: rgba(0, 0, 0, 0.75);
            backdrop-filter: blur(60px) saturate(220%);
            -webkit-backdrop-filter: blur(60px) saturate(220%);
            border-right: 1px solid var(--widget-border);
            z-index: 1000;
            transform: translateX(-100%);
            transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
            display: flex;
            flex-direction: column;
            padding-top: var(--safe-top);
            padding-bottom: var(--safe-bottom);
        }

        #sidebar.open {
            transform: translateX(0);
        }

        #sidebar-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            z-index: 999;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.4s cubic-bezier(0.25, 1, 0.5, 1);
        }

        #sidebar-overlay.visible {
            opacity: 1;
            pointer-events: auto;
        }

        #sidebar-header {
            padding: 24px 20px 0;
            border-bottom: none;
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 20px;
        }

        #sidebar-header h2 {
            font-size: 1.1rem;
            font-weight: 500;
            color: var(--text-primary);
            letter-spacing: -0.02em;
        }

        #sidebar-close {
            background: transparent;
            border: none;
            color: var(--text-secondary);
            font-size: 1.5rem;
            cursor: pointer;
            padding: 4px;
            width: 28px;
            height: 28px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: color 0.2s ease;
        }

        #sidebar-close:hover {
            color: var(--text-primary);
        }

        #new-chat-button {
            margin: 0 20px 20px;
            padding: 10px 16px;
            background: rgba(41, 151, 255, 0.1);
            backdrop-filter: blur(20px) saturate(200%);
            -webkit-backdrop-filter: blur(20px) saturate(200%);
            color: var(--accent-blue);
            border: 1px solid rgba(41, 151, 255, 0.2);
            border-radius: 10px;
            font-size: 0.9rem;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            transition: all 0.2s ease;
        }

        #new-chat-button:hover {
            background: rgba(41, 151, 255, 0.2);
            border-color: rgba(41, 151, 255, 0.4);
            transform: translateY(-1px);
        }

        #new-chat-button svg {
            width: 16px;
            height: 16px;
        }

        #past-chats-container {
            flex: 1;
            overflow-y: auto;
            padding: 0 20px;
            -webkit-overflow-scrolling: touch;
            scrollbar-width: thin;
            scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
        }

        #past-chats-container::-webkit-scrollbar {
            width: 4px;
        }

        #past-chats-container::-webkit-scrollbar-track {
            background: transparent;
        }

        #past-chats-container::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.15);
            border-radius: 2px;
        }

        .past-chat-item {
            padding: 14px 16px;
            margin-bottom: 4px;
            background: rgba(255, 255, 255, 0.02);
            border: 1px solid transparent;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.2s ease;
            position: relative;
        }

        .past-chat-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: transparent;
            border-radius: 12px;
            transition: background 0.2s ease;
        }

        .past-chat-item:hover::before {
            background: rgba(41, 151, 255, 0.1);
        }

        .past-chat-item.active::before {
            background: rgba(41, 151, 255, 0.2);
        }

        .past-chat-item:hover {
            border-color: rgba(41, 151, 255, 0.3);
        }

        .past-chat-item.active {
            border-color: var(--accent-blue);
        }

        .past-chat-title {
            font-size: 0.95rem;
            font-weight: 500;
            color: var(--text-primary);
            margin-bottom: 2px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .past-chat-item.active .past-chat-title {
            color: var(--text-primary);
        }

        .past-chat-date {
            font-size: 0.75rem;
            color: var(--text-secondary);
            letter-spacing: -0.01em;
        }

        .past-chat-item.active .past-chat-date {
            color: rgba(255, 255, 255, 0.7);
        }

        #menu-toggle {
            background: transparent;
            border: none;
            color: var(--text-secondary);
            padding: 6px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: color 0.2s ease;
        }

        #menu-toggle:hover {
            color: var(--text-primary);
        }

        #menu-toggle svg {
            width: 20px;
            height: 20px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
            background: var(--bg-color);
            color: var(--text-primary);
            height: 100dvh;
            width: 100vw;
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }

        #canvas-bg {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: -1;
            opacity: 0.12;
        }

        #chat-view {
            display: flex;
            flex-direction: column;
            width: 100%;
            height: 100%;
            background: transparent;
            transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1), filter 0.5s cubic-bezier(0.25, 1, 0.5, 1), border-radius 0.5s cubic-bezier(0.25, 1, 0.5, 1);
        }

        #chat-view.research-active {
            transform: scale(0.98);
            filter: brightness(0.85);
            border-radius: 24px;
            overflow: hidden;
            pointer-events: none;
        }

        .frosted-header {
            position: sticky;
            top: 0;
            width: 100%;
            background: var(--header-footer-bg);
            backdrop-filter: blur(30px) saturate(200%);
            -webkit-backdrop-filter: blur(30px) saturate(200%);
            z-index: 10;
            padding: 16px 20px;
            padding-top: calc(16px + var(--safe-top));
            border-bottom: 1px solid var(--widget-border);
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .frosted-header h1 {
            font-size: 1.05rem;
            font-weight: 500;
            opacity: 0.95;
            flex: 1;
            text-align: center;
            letter-spacing: -0.02em;
        }

        #chat-history {
            flex-grow: 1;
            overflow-y: auto;
            -webkit-overflow-scrolling: touch;
            padding: 1.75rem 1.25rem;
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
            scroll-behavior: smooth;
        }

        @keyframes message-pop-in {
            from {
                opacity: 0;
                transform: translateY(8px) scale(0.98);
            }
            to {
                opacity: 1;
                transform: translateY(0) scale(1.0);
            }
        }

        .message {
            max-width: 85%;
            padding: 14px 20px;
            border-radius: 22px;
            line-height: 1.55;
            font-size: 0.98rem;
            overflow-wrap: break-word;
            white-space: pre-wrap;
            font-weight: 400;
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            border: 1px solid rgba(255, 255, 255, 0.08);
